import { AInvoker } from "ainvoker"
import { z } from "zod"

const ai = new AInvoker({
  apiKey: process.env.AINVOKER_API_KEY!,
})

const themeDef = ai.action.define({
  name: "toggle_theme",
  description: "Toggle theme UI to dark and light mode",
  inputSchema: z.object({
    theme: z.enum(["light", "dark", "system"]),
  }),
  method: ({ theme }) => setTheme(theme),
})

const result = await ai.action.invoke({
  model: "openai/gpt-4o-mini",
  tools: [themeDef],
  prompt: "Switch theme to dark",
})

console.log(result.message.content)
